const all = $input.all();
const items = [];
for (const branch of all) {
  const payload = branch.json;
  const body = String(payload.body || payload.data || '');
  const domain = (payload.url || '').replace(/^https?:\/\//i,'').split('/')[0] || 'unknown';
  const titles = [];
  const re = /<item>[\s\S]*?<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/gi;
  let m, c=0;
  const cap = $json.max_items_per_feed || 8;
  while ((m = re.exec(body)) !== null && c < cap) { titles.push(m[1].replace(/<[^>]+>/g,'').trim()); c++; }
  items.push({ domain: domain, item_count: titles.length, top_title: titles[0] || null, titles_sample: titles.slice(0,3) });
}
const total = items.reduce((a,b)=>a+b.item_count,0);
const top_titles = items.slice(0,2).map(i=>i.top_title).filter(Boolean);
let h = 2166136261;
const s = JSON.stringify(items);
for (let i=0;i<s.length;i++){ h ^= s.charCodeAt(i); h = Math.imul(h,16777619); }
return [{ json: { digest_id: 'osint-news-radar-fnv1a-' + ('0000000'+(h>>>0).toString(16)).slice(-8), sources: items.map(i=>i.domain), total_items: total, top_titles: top_titles, stale: false, timestamp_iso: new Date().toISOString() } }];
